#include <torch/extension.h>
#include <cuda_runtime.h>

#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Define tile size
    const int TILE_SIZE = 16;

    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread indices
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles with unrolling
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    int t;
    for (t = 0; t < numTiles - UNROLL_FACTOR + 1; t += UNROLL_FACTOR) {
        #pragma unroll
        for (int u = 0; u < UNROLL_FACTOR; u++) {
            // Load tile of A into shared memory
            int tiledRow = (t + u) * TILE_SIZE + threadIdx.y;
            int tiledCol = (t + u) * TILE_SIZE + threadIdx.x;

            if (row < N && tiledCol < N) {
                As[threadIdx.y][threadIdx.x] = A[row * N + tiledCol];
            } else {
                As[threadIdx.y][threadIdx.x] = 0.0f;
            }

            // Load tile of B into shared memory
            if (tiledRow < N && col < N) {
                Bs[threadIdx.y][threadIdx.x] = B[tiledRow * N + col];
            } else {
                Bs[threadIdx.y][threadIdx.x] = 0.0f;
            }

            // Synchronize to make sure tiles are loaded
            __syncthreads();

            // Compute partial dot product
            for (int k = 0; k < TILE_SIZE; k++) {
                sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
            }

            // Synchronize before loading next tile
            __syncthreads();
        }
    }

    // Process remaining tiles
    for (; t < numTiles; t++) {
        // Load tile of A into shared memory
        int tiledRow = t * TILE_SIZE + threadIdx.y;
        int tiledCol = t * TILE_SIZE + threadIdx.x;

        if (row < N && tiledCol < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + tiledCol];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        if (tiledRow < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[tiledRow * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Synchronize to make sure tiles are loaded
        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        // Synchronize before loading next tile
        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Set block size to match tile size
    dim3 block_size(16, 16);
    dim3 grid_size((N + block_size.x - 1) / block_size.x, (N + block_size.y - 1) / block_size.y);

    matmul_kernel<<<grid_size, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

